#!/bin/bash
exec python3 /app/bandit.pyc "$@"

(exit_code=0)

function.arguments:
{"command": "python3 -c "
import importlib.util
spec = importlib.util.spec_from_file_location('bandit', '/app/bandit.pyc')
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
# Print all attributes and methods
for name in dir(module):
    if not name.startswith('_'):
        print(f'{name}: {type(getattr(module, name))}')
""}
